@CrossOrigin
@RestController
@RequestMapping("/ATM")
public class ATMRestController extends BaseSpringRestController {

	public ATMRestController( ATMService service ) {
		this.service = service;
	}
    /**
     * Handles create a ATM.  if not key provided, calls create, otherwise calls save
     * @param		ATM	aTM
     * @return		ATM 
     */
	@PostMapping("/create")
    public ATM create( @RequestBody(required=true) CreateATMCommand command ) {
    	ATM entity = null;

		entity = service.createATM( command );
		LOGGER.info( "Successfully created ATM with Id " + entity.getATMId()  );

		return entity;
    }

    /**
     * Handles updating a ATM.  if no key provided, calls create, otherwise calls save
     * @param		ATM aTM
     * @return		ATM
     */
	@PutMapping("/update")
    public ATM update( @RequestBody(required=true) UpdateATMCommand command ) {
		ATM entity = null;

		entity = service.updateATM(command);
		LOGGER.info( "Successfully updated ATM with Id " + command.getATMId()  );

		return entity;
	}
 
    /**
     * Handles deleting a ATM entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteATMCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted ATM with Id " + command.getATMId()  );
	}
	
    /**
     * Handles loading a ATM using a UUID
     * @param		UUID uuid 
     * @return		ATM
     */    
    @GetMapping("/load")
    public ATM load( @RequestParam(required=true) UUID uuid ) {
    	ATM entity = service.getATM( new ATMFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded ATM with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all ATM business objects
     * @return		Set<ATM>
     */
    @GetMapping("/")
    public List<ATM> loadAll() {                
    	List<ATM> aTMList = null;

		aTMList = service.getAllATM();
		LOGGER.info( "successfully loaded all ATMs" );

        return aTMList;
                            
    }

    /**
     * save Branch on ATM
     * @param		command AssignBranchToATMCommand
     */     
	@PutMapping("/assignBranch")
	public void assignBranch( @RequestBody AssignBranchToATMCommand command ) {
		service.assignBranch( command );
		LOGGER.info( "Successfully assigned Branch with Id " + command.getATMId()  );
	}

    /**
     * unassign Branch on ATM
     * @param		 command UnAssignBranchFromATMCommand
     */     
	@PutMapping("/unAssignBranch")
	public void unAssignBranch( @RequestBody(required=true)  UnAssignBranchFromATMCommand command ) {
		service.unAssignBranch( command );
		LOGGER.info( "Successfully unassigned Branch with Id " + command.getATMId()  );
	}
	




//************************************************************************    
// Attributes
//************************************************************************
    protected ATM aTM = null;
	protected ATMService service = null;
    private static final Logger LOGGER = LoggerFactory.getLogger(ATMRestController.class.getName());
    
}
